func clearAuthCaches() {
	appTokenCache.Range(func(k, v interface{}) bool {
		appTokenCache.Delete(k)
		return true
	})
	ownerTokenCache.Range(func(k, v interface{}) bool {
		ownerTokenCache.Delete(k)
		return true
	})
	chairTokenCache.Range(func(k, v interface{}) bool {
		chairTokenCache.Delete(k)
		return true
	})
}

func appAuthMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		ctx := r.Context()
		c, err := r.Cookie("app_session")
		if errors.Is(err, http.ErrNoCookie) || c.Value == "" {
			writeError(w, http.StatusUnauthorized, errors.New("app_session cookie is required"))
			return
		}
		accessToken := c.Value
		if v, ok := appTokenCache.Load(accessToken); ok {
			user := &User{ID: v.(string)}
			next.ServeHTTP(w, r.WithContext(context.WithValue(ctx, "user", user)))
			return
		}
		user := &User{}
		err = db.GetContext(ctx, user, "SELECT * FROM users WHERE access_token = ?", accessToken)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				writeError(w, http.StatusUnauthorized, errors.New("invalid access token"))
				return
			}
			writeError(w, http.StatusInternalServerError, err)
			return
		}
		appTokenCache.Store(accessToken, user.ID)
		ctx = context.WithValue(ctx, "user", user)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

