	for _, ride := range rides {
		bestIndex := -1
		bestTime := math.MaxFloat64
		bestDistance := math.MaxInt32
		rideDistance := abs(ride.PickupLatitude-ride.DestinationLatitude) + abs(ride.PickupLongitude-ride.DestinationLongitude)
		for i, chair := range chairs {
			if used[chair.ID] || chair.Speed <= 0 {
				continue
			}
			pickupDistance := abs(chair.Latitude-ride.PickupLatitude) + abs(chair.Longitude-ride.PickupLongitude)
			estimatedTime := float64(pickupDistance+rideDistance) / float64(chair.Speed)
			if estimatedTime < bestTime || (estimatedTime == bestTime && pickupDistance < bestDistance) {
				bestIndex = i
				bestTime = estimatedTime
				bestDistance = pickupDistance
			}
		}
		if bestIndex < 0 {
			break
		}

		chair := chairs[bestIndex]
		tx, err := db.BeginTxx(ctx, nil)
		if err != nil {
			return
		}

		result, err := tx.ExecContext(ctx, `UPDATE rides SET chair_id = ? WHERE id = ? AND chair_id IS NULL`, chair.ID, ride.ID)
		if err != nil {
			tx.Rollback()
			continue
		}
		affected, err := result.RowsAffected()
		if err != nil || affected == 0 {
			tx.Rollback()
			continue
		}

		result, err = tx.ExecContext(ctx, `UPDATE chairs SET current_ride_id = ? WHERE id = ? AND current_ride_id IS NULL`, ride.ID, chair.ID)
		if err != nil {
			tx.Rollback()
			continue
		}
		affected, err = result.RowsAffected()
		if err != nil || affected == 0 {
			tx.Rollback()
			continue
		}

		if err := tx.Commit(); err != nil {
			continue
		}
		used[chair.ID] = true
	}
